from pathlib import Path
import json,html,urllib.parse,collections
OUT=Path(__file__).resolve().parents[1];meta=json.loads((OUT/'render-metadata.json').read_text());rows=meta['entries'];e=html.escape
families=sorted(set(r['family'] for r in rows));projects=sorted(set(r['representative_repo'] for r in rows))
css='''
:root{--ink:#182c29;--muted:#63746d;--paper:#f3f2eb;--line:#d8ded4;--accent:#187663;--dark:#101a27}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.6 system-ui,-apple-system,sans-serif}a{color:var(--accent);text-underline-offset:3px}header{background:#183b32;color:#fff;padding:60px max(28px,calc((100vw - 1360px)/2)) 38px}.eyebrow{font:600 12px/1.5 ui-monospace,monospace;text-transform:uppercase;letter-spacing:2px;color:#a9d8bf}h1{font-size:clamp(32px,4vw,58px);line-height:1.12;letter-spacing:-2px;margin:12px 0 18px}header p{max-width:840px;color:#cee0d5;font-size:17px}header a{color:#beeacc}.stats{display:flex;gap:38px;flex-wrap:wrap;margin-top:30px}.stat strong{display:block;font-size:29px;font-weight:600}.stat span{color:#b5cdbf;font-size:13px}main{max-width:1416px;padding:28px;margin:auto}.method{display:grid;grid-template-columns:1.8fr 1fr;gap:32px;border-bottom:1px solid var(--line);padding:0 0 24px}.method p{margin:0;color:var(--muted)}.legend{display:flex;gap:12px;flex-wrap:wrap;align-content:center;font-size:12px}.legend span::before{content:'';display:inline-block;width:9px;height:9px;border-radius:50%;background:var(--color);margin-right:6px}.toolbar{position:sticky;top:0;background:#f3f2ebf5;backdrop-filter:blur(10px);z-index:2;padding:20px 0 14px}.controls{display:grid;grid-template-columns:2fr 1.5fr 1.3fr 1fr;gap:12px}label{font-size:11px;color:var(--muted);font-weight:650;letter-spacing:.6px;text-transform:uppercase}input,select{display:block;width:100%;margin-top:5px;border:1px solid #cbd4c9;border-radius:8px;background:#fff;padding:12px;color:var(--ink);font:14px system-ui;min-width:0}input:focus,select:focus{outline:2px solid #187663;outline-offset:2px}.resultbar{display:flex;justify-content:space-between;align-items:center;margin-top:12px;color:var(--muted);font-size:13px}button{font:inherit;cursor:pointer}#reset{border:0;background:none;text-decoration:underline;color:var(--accent)}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.card{scroll-margin-top:165px;background:#fff;border:1px solid var(--line);border-radius:14px;overflow:hidden;box-shadow:0 4px 16px #183b3205}.card[hidden]{display:none}.cardhead{padding:20px 22px 15px}.kicker{display:flex;justify-content:space-between;gap:12px;font-size:11px;font-weight:650;letter-spacing:.7px;text-transform:uppercase;color:var(--muted)}.badge{color:#846123}.card h2{font-size:21px;line-height:1.3;letter-spacing:-.4px;margin:8px 0 8px}.name{font:12px/1.6 ui-monospace,monospace;overflow-wrap:anywhere;color:#6c7771;min-height:38px}.scene{position:relative;background:var(--dark)}.detail{display:block;width:100%;padding:0;border:0;background:var(--dark)}.detail img{display:block;width:100%;height:auto;aspect-ratio:10/7}.inset{position:absolute;bottom:14px;right:14px;width:30%;border:1px solid #638778;border-radius:8px;background:var(--dark);color:#d1e7df;padding:0;overflow:hidden;box-shadow:0 3px 12px #0008}.inset img{display:block;width:100%;aspect-ratio:1.6}.inset span{display:block;font-size:10px;padding:2px 0 4px}.scene-label{position:absolute;left:12px;top:10px;font:11px ui-monospace,monospace;color:#d8e9df;background:#101a27dc;padding:5px 8px;border-radius:5px;pointer-events:none}.cardbody{padding:16px 22px 20px}.metadata{display:grid;grid-template-columns:1.5fr 1fr 1fr;gap:16px;font-size:13px;line-height:1.5}.metadata small{display:block;color:var(--muted);font-size:10px;letter-spacing:.8px;text-transform:uppercase;margin-bottom:4px}.metadata div{overflow-wrap:anywhere}.links{display:flex;flex-wrap:wrap;gap:7px 18px;font-size:12px;margin:16px 0 10px}.license{font-size:11px;color:var(--muted);border-top:1px solid #e7eae3;padding-top:10px}.note{font-size:12px;color:#8b6122;margin:10px 0 0}.empty{display:none;text-align:center;padding:60px}.footer{padding:35px 0;color:var(--muted);font-size:12px}dialog{border:1px solid #536a60;border-radius:14px;max-width:min(1240px,95vw);padding:0;background:var(--dark);color:#fff}dialog::backdrop{background:#07110ee6}dialog .bar{display:flex;justify-content:space-between;align-items:center;padding:14px 20px;gap:20px}dialog img{display:block;max-width:100%;max-height:80vh;margin:auto}dialog button{background:#284237;border:1px solid #618172;border-radius:6px;color:#fff;padding:6px 12px}dialog p{font-size:12px;color:#c4d6cb;margin:0 20px 16px}@media(max-width:800px){header{padding:36px 20px}.method{grid-template-columns:1fr;gap:16px}main{padding:20px}.grid{grid-template-columns:1fr}.controls{grid-template-columns:1fr 1fr}.toolbar{position:static}.stats{gap:24px}.metadata{font-size:12px}h1{letter-spacing:-1px}}@media print{header{background:white;color:black;padding:0}header p,.eyebrow,.stat span{color:#444}.toolbar,.inset,.links,dialog{display:none}.grid{display:block}.card{break-inside:avoid;margin:20px 0}.cardhead{padding:10px}.detail img{max-height:330px;object-fit:contain}.method{display:block}main{padding:0}.cardbody{padding:10px}}
'''
parts=['<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Footprints in context · Keyboard source survey</title><style>'+css+'</style></head><body>',
'''<header><div class="eyebrow">Ergogen footprint library / Visual source survey / 25 October 2026</div><h1>Footprints in context.</h1><p>Missing footprint candidates, shown where they are actually placed. Explore the pads, nearby routing and board location before choosing what to convert.</p><div class="stats"><div class="stat"><strong>210</strong><span>KiCad candidates · includes 1 under review</span></div><div class="stat"><strong>67</strong><span>Missing KiCad families</span></div><div class="stat"><strong>420</strong><span>Board renders & close-ups</span></div></div></header>
<main><section class="method"><p>These are <strong>2D renders of the source PCB files</strong>, plotted by KiCad, with a mint box marking the selected footprint. Each entry shows one representative placed instance; click either image to enlarge it. Views include the selected side’s copper, silkscreen and board outline. <strong>Both sides use the same top-down coordinates</strong>; back views are not mirrored. They are layout images, not photographs or assembled 3D models.</p><div class="legend"><span style="--color:#c83434">Front copper</span><span style="--color:#4d7fc4">Back copper</span><span style="--color:#c6bd63">Silkscreen / board outline</span><span style="--color:#64e6d2">Selected footprint</span><span><a href="../REPORT.md">Research & license notes</a></span></div></section>
<div class="toolbar"><div class="controls"><label>Search<input id="search" placeholder="Part, footprint, keyboard or reference…" type="search"></label><label>Component family<select id="family"><option value="">All families</option>''']
parts.extend('<option>'+e(f)+'</option>' for f in families)
parts.append('</select></label><label>Source project<select id="project"><option value="">All projects</option>')
parts.extend('<option>'+e(p)+'</option>' for p in projects)
parts.append('''</select></label><label>Status<select id="format"><option value="">All entries</option><option value="missing">Missing</option><option value="review">Needs review</option></select></label></div><div class="resultbar"><span id="count" aria-live="polite"></span><button id="reset">Clear filters</button></div></div><div class="grid">''')
priority=['Seeed XIAO BLE SMD cutout','Raspberry Pi Pico module','Waveshare RP2040-Zero module','WeAct STM32 Black Pill module','MJ-4PP-9 TRRS jack','USB-C receptacles','12-pin 0.5mm FPC (Cirque touchpad)','PixArt PMW3360 sensor (DIP-16 W10.16mm)','Pimoroni DRV2605L haptic module','Tenting puck mounting pattern']
for r in sorted(rows,key=lambda r:(priority.index(r['family']) if r['family'] in priority else len(priority),r['family'].lower(),r['id'])):
 f=r['placement'];id=r['id'];side='Front' if f['side']=='F' else 'Back';search=' '.join([r['family'],r['footprint'],r['representative_repo'],f['reference'],r['license'],id]).lower();attrs=' '.join(f'data-{k}="{e(v,quote=True)}"' for k,v in [('family',r['family']),('project',r['representative_repo']),('format',r['format']),('status',r['status']),('search',search)])
 title=e(r['family']);name=e(r['footprint']);ref=e(f['reference']);project=e(r['representative_repo']);caption=f'{id} · {r["family"]} · {r["representative_repo"]} · {f["reference"]} · {side}'
 parts.append(f'<article class="card" id="{id}" {attrs}><div class="cardhead"><div class="kicker"><span>{id} / {e(r["format"])}</span><span class="badge">'+('Needs identification' if r['status']=='review' else 'Missing from library')+f'</span></div><h2>{title}</h2><div class="name">{name}</div></div><div class="scene"><button class="detail enlarge" data-caption="{e(caption,quote=True)}" aria-label="Enlarge {id} close-up"><img loading="lazy" src="images/{id}-detail.png" alt="{e(caption,quote=True)} close-up"></button><span class="scene-label">{side.upper()} · {ref}</span><button class="inset enlarge" data-caption="{e(caption,quote=True)} · board location" aria-label="Enlarge {id} board location"><img loading="lazy" src="images/{id}-board.png" alt="Location of {ref} on source board"><span>BOARD LOCATION ↗</span></button></div><div class="cardbody"><div class="metadata"><div><small>Source project</small>{project}</div><div><small>Placed reference</small>{ref}</div><div><small>Pad objects</small>{f["pads"]}</div></div><div class="links"><a href="{e(r["board_url"],quote=True)}" target="_blank" rel="noopener">Upstream PCB ↗</a>')
 if r.get('embedded_source'):parts.append(f'<a href="../{urllib.parse.quote(r["embedded_source"],safe="/._-")}">Placed source</a>')
 if r.get('standalone_sources'):parts.append(f'<a href="../{urllib.parse.quote(r["standalone_sources"][0]["file"],safe="/._-")}">Library footprint</a>')
 parts.append(f'<a href="../{r["license_folder"]}/">License evidence</a></div><div class="license">{e(r["license"])} · revision {r["commit"][:12]}</div>')
 if r['status']=='review':parts.append('<p class="note">Part label is ambiguous. Verify against SK6812 MINI-E before treating it as a separate component.</p>')
 if f['pads']==0:parts.append('<p class="note">Mechanical footprint: inspect its holes, outline or courtyard rather than electrical pads.</p>')
 parts.append('</div></article>')
parts.append('''</div><p class="empty" id="empty">No matching footprints. Try another part name or clear the filters.</p><footer class="footer">Original files, attribution and license terms remain in the parent survey folder. Combined switch footprints are omitted from this candidate gallery; surrounding switches remain visible on the source PCBs. Copper fills are plotted as saved. Scale bars measure board coordinates, not manufacturing tolerances. Font substitution and legacy-format interpretation may affect appearance. Pad-object counts include mechanical and duplicate-number pads. Rendering does not validate electrical or manufacturing correctness.<br><a href="render-metadata.json">Placement and rendering metadata</a> · <a href="../EXACT-FOOTPRINTS.md">Exact footprint inventory</a> · <a href="../REPORT.md">Full research report</a></footer></main><dialog id="viewer"><div class="bar"><strong id="caption"></strong><button id="close">Close ×</button></div><img id="large" alt=""><p>Mint box = selected footprint. Back views retain top-down board coordinates.</p></dialog><script>
const cards=[...document.querySelectorAll('.card')], fields=['search','family','project','format'].map(x=>document.getElementById(x));
function filter(){const [q,f,p,t]=fields.map(x=>x.value);let n=0;for(const c of cards){const ok=(!q||c.dataset.search.includes(q.toLowerCase()))&&(!f||c.dataset.family===f)&&(!p||c.dataset.project===p)&&(!t||c.dataset.status===t);c.hidden=!ok;if(ok)n++}document.getElementById('count').textContent=`${n} of ${cards.length} footprint entries · click images to inspect`;document.getElementById('empty').style.display=n?'none':'block'}fields.forEach(x=>x.addEventListener('input',filter));document.getElementById('reset').onclick=()=>{fields.forEach(x=>x.value='');filter()};filter();const dialog=document.getElementById('viewer');document.querySelectorAll('.enlarge').forEach(b=>b.onclick=()=>{const im=b.querySelector('img');document.getElementById('large').src=im.src;document.getElementById('large').alt=im.alt;document.getElementById('caption').textContent=b.dataset.caption;dialog.showModal()});document.getElementById('close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
</script></body></html>''')
(OUT/'index.html').write_text('\n'.join(parts));print('Report built:',len(rows),'entries')
